{"filename":"page_cycle.js","content":"(function(){
  window.ForgeAI.registerPage('cycle', async function(ctx){
    const root = ctx.root;
    root.innerHTML = '';
    const container = document.createElement('div');
    container.className = 'cycle-page';

    const header = document.createElement('div');
    header.className = 'page-header';
    const title = document.createElement('h2');
    title.textContent = 'Cycles';
    const addBtn = document.createElement('button');
    addBtn.className = 'btn primary';
    addBtn.textContent = 'Add Cycle';
    header.appendChild(title);
    header.appendChild(addBtn);
    container.appendChild(header);

    const table = document.createElement('table');
    table.className = 'cycle-table';
    const thead = document.createElement('thead');
    const trHead = document.createElement('tr');
    ['ID','Cycle Number','Average Length','Average Flow','Actions'].forEach(text=>{const th=document.createElement('th');th.textContent=text;trHead.appendChild(th);});
    thead.appendChild(trHead);
    table.appendChild(thead);
    const tbody = document.createElement('tbody');
    table.appendChild(tbody);
    container.appendChild(table);
    root.appendChild(container);

    function showToast(msg,type='info'){
      const toast = document.createElement('div');
      toast.className = `toast ${type}`;
      toast.textContent = msg;
      document.body.appendChild(toast);
      setTimeout(()=>{toast.remove();},3000);
    }

    async function loadCycles(){
      tbody.innerHTML = '';
      const loadingRow = document.createElement('tr');
      const loadingCell = document.createElement('td');
      loadingCell.colSpan = 5;
      loadingCell.textContent = 'Loading...';
      loadingRow.appendChild(loadingCell);
      tbody.appendChild(loadingRow);
      try{
        const resp = await ctx.api('/api/cycles',{method:'GET'});
        if(!resp.success){throw new Error('API failure');}
        const data = resp.data || [];
        tbody.innerHTML = '';
        data.forEach(cycle=>{
          const tr=document.createElement('tr');
          const tdId=document.createElement('td'); tdId.textContent = cycle.id;
          const tdNum=document.createElement('td'); tdNum.textContent = cycle.cycle_number;
          const tdLen=document.createElement('td'); tdLen.textContent = cycle.average_length;
          const tdFlow=document.createElement('td'); tdFlow.textContent = cycle.average_flow;
          const tdAct=document.createElement('td');
          const viewBtn=document.createElement('button');
          viewBtn.className = 'btn small';
          viewBtn.textContent = 'View';
          viewBtn.addEventListener('click',()=>{showDetails(cycle);});
          tdAct.appendChild(viewBtn);
          tr.appendChild(tdId);
          tr.appendChild(tdNum);
          tr.appendChild(tdLen);
          tr.appendChild(tdFlow);
          tr.appendChild(tdAct);
          tbody.appendChild(tr);
        });
      }catch(e){
        tbody.innerHTML = '';
        const errRow=document.createElement('tr');
        const errCell=document.createElement('td');
        errCell.colSpan = 5;
        errCell.textContent = 'Error loading cycles';
        errRow.appendChild(errCell);
        tbody.appendChild(errRow);
        showToast('Failed to load cycles','error');
      }
    }

    function showDetails(cycle){
      alert(`Cycle #${cycle.cycle_number}\nAverage Length: ${cycle.average_length}\nAverage Flow: ${cycle.average_flow}`);
    }

    function openAddModal(){
      const modal=document.createElement('div');
      modal.className = 'modal';
      const modalContent=document.createElement('div');
      modalContent.className = 'modal-content';
      const closeBtn=document.createElement('span');
      closeBtn.className = 'close';
      closeBtn.innerHTML = '&times;';
      closeBtn.addEventListener('click',()=>{modal.remove();});
      const form=document.createElement('form');
      form.innerHTML = `
        <h3>Add Cycle</h3>
        <label>Cycle Number<input type="number" name="cycle_number" required></label>
        <label>Average Length<input type="number" name="average_length" required></label>
        <label>Average Flow<input type="text" name="average_flow"></label>
        <button type="submit" class="btn primary">Save</button>
      `;
      form.addEventListener('submit', async (e)=>{
        e.preventDefault();
        const formData = new FormData(form);
        const payload = {
          cycle_number: parseInt(formData.get('cycle_number')),
          average_length: parseInt(formData.get('average_length')),
          average_flow: formData.get('average_flow')
        };
        try{
          const resp = await ctx.api('/api/cycles',{method:'POST',body:JSON.stringify(payload),headers:{'Content-Type':'application/json'}});
          if(resp.success){
            showToast('Cycle added','success');
            modal.remove();
            loadCycles();
          }else{throw new Error('API error');}
        }catch(err){
          showToast('Failed to add cycle','error');
        }
      });
      modalContent.appendChild(closeBtn);
      modalContent.appendChild(form);
      modal.appendChild(modalContent);
      document.body.appendChild(modal);
    }

    addBtn.addEventListener('click',openAddModal);
    await loadCycles();
  });
})();"}
